import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function EmotionRecommendPage({ movies = [] }) {
  const [selectedEmotion, setSelectedEmotion] = useState(null);
  const [recommendedMovie, setRecommendedMovie] = useState(null);
  const [loading, setLoading] = useState(false);

  const emotionOptions = [
    { id: 'comfort', label: '나는 오늘 위로가 필요해' },
    { id: 'laugh', label: '나는 오늘 웃음이 필요해' },
    { id: 'thrill', label: '나는 오늘 짜릿한 자극이 필요해' },
    { id: 'romance', label: '나는 오늘 설렘이 필요해' }
  ];

  const handleSelectEmotion = (option) => {
    setSelectedEmotion(option.label);
    setLoading(true);
    setRecommendedMovie(null);

    setTimeout(() => {
      let chosen = null;

      if (movies && movies.length > 0) {
        const randomIndex = Math.floor(Math.random() * movies.length);
        chosen = movies[randomIndex];
      }

      if (!chosen) {
        chosen = {
          title: '메가박스 시그니처 추천작',
          overview: '오늘 당신의 기분에 완벽하게 어울리는 감동적인 상영작입니다.',
          poster_path: null,
          backdrop_path: null
        };
      }

      setRecommendedMovie(chosen);
      setLoading(false);
    }, 500);
  };

  return (
    <div 
      className="w-full min-h-screen py-16 px-6 flex flex-col items-center justify-center relative bg-cover bg-center bg-fixed text-white" 
      style={{ 
        fontFamily: 'Pretendard, sans-serif',
        /* 💡 투명한 유리 효과를 극대화하기 위해 임시 배경 이미지를 넣었습니다. 
           원하시는 배경 이미지 경로로 변경하시거나, 기존 배경색을 쓰시려면 이 줄을 지워주세요. */
        backgroundImage: "url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')"
      }}
    >
      {/* 💡 글래스모피즘 메인 패널 (반투명 + 블러 처리 + 흰색 테두리) */}
      <div className="w-full max-w-3xl relative overflow-hidden bg-white/10 backdrop-blur-2xl border border-white/20 shadow-[0_8px_32px_0_rgba(0,0,0,0.3)] rounded-[40px] p-8 md:p-12 space-y-10">
        
        {/* 상단 반사광 효과 (유리 느낌을 더해주는 디테일) */}
        <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-white/10 to-transparent pointer-events-none"></div>

        {/* 상단 캐릭터 및 타이틀 영역 */}
        <div className="text-center space-y-4 relative z-10">
          <div className="flex justify-center items-end gap-4 mb-4">
            <img 
              src="/img/02.png"
              alt="Megabox Emotion Characters" 
              className="h-28 md:h-36 object-contain drop-shadow-[0_10px_10px_rgba(0,0,0,0.5)] hover:scale-105 transition-transform duration-300" 
            />
          </div>

          <span className="inline-block text-[11px] font-black tracking-widest text-purple-200 uppercase bg-white/10 backdrop-blur-md px-4 py-1.5 rounded-full border border-white/20 shadow-sm">
            MEGABOX EMOTION CARE
          </span>
          <h2 className="text-3xl md:text-4xl font-black text-white tracking-tight drop-shadow-md">
            오늘의 감정에 맞는 영화를 골라드려요
          </h2>
          <p className="text-xs text-zinc-300 font-medium">
            마음이 끌리는 문구를 선택하시면, 현재 상영작 중 가장 잘 어울리는 영화를 추천해 드립니다.
          </p>
        </div>

        {/* 문체형 선택 버튼 그리드 (투명한 유리 버튼) */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 relative z-10">
          {emotionOptions.map((option) => (
            <button
              key={option.id}
              onClick={() => handleSelectEmotion(option)}
              className={`p-5 rounded-2xl text-left font-black text-sm transition-all duration-300 backdrop-blur-md border ${
                selectedEmotion === option.label
                  ? 'bg-white/30 text-white border-white/50 shadow-[0_0_20px_rgba(255,255,255,0.2)] scale-[1.02]'
                  : 'bg-white/5 hover:bg-white/15 text-zinc-200 border-white/10 hover:border-white/30'
              }`}
            >
              <div className="flex items-center justify-between">
                <span>{option.label}</span>
                <span className="text-lg opacity-80">✨</span>
              </div>
            </button>
          ))}
        </div>

        {/* 로딩 상태 */}
        {loading && (
          <div className="text-center py-12 text-white font-bold animate-pulse text-sm">
            친구들이 마음에 쏙 드는 영화를 찾는 중입니다...
          </div>
        )}

        {/* 추천 결과 카드 (투명 유리 카드) */}
        {recommendedMovie && !loading && (
          <div className="bg-white/10 backdrop-blur-lg border border-white/20 rounded-3xl p-8 shadow-xl flex flex-col md:flex-row items-center gap-8 animate-fade-in relative z-10">
            
            {/* 포스터 영역 */}
            <div className="w-44 h-60 rounded-2xl bg-black/20 overflow-hidden shadow-2xl shrink-0 border border-white/10 flex items-center justify-center relative">
              {recommendedMovie.poster_path || recommendedMovie.backdrop_path ? (
                <img 
                  src={`https://image.tmdb.org/t/p/w500${recommendedMovie.poster_path || recommendedMovie.backdrop_path}`} 
                  alt={recommendedMovie.title} 
                  className="w-full h-full object-cover" 
                />
              ) : (
                <span className="text-xs text-zinc-400 font-bold">MEGABOX MOVIE</span>
              )}
            </div>

            {/* 컨텐츠 및 설명 영역 */}
            <div className="flex flex-col justify-center space-y-4 text-left w-full">
              <div>
                <span className="text-[11px] font-black text-purple-200 bg-white/10 px-3 py-1 rounded-full border border-white/20 backdrop-blur-md">
                  {selectedEmotion}
                </span>
                <h3 className="text-2xl md:text-3xl font-black text-white mt-3 mb-2 drop-shadow-md">
                  {recommendedMovie.title}
                </h3>
                <p className="text-xs text-zinc-300 leading-relaxed font-medium line-clamp-3">
                  {recommendedMovie.overview || "일상에 특별한 감동과 여운을 선사할 추천 상영작입니다."}
                </p>
              </div>

              {/* 하단 액션 버튼 */}
              <div className="flex gap-3 pt-2">
                <Link 
                  to="/schedule" 
                  className="flex-grow text-center py-3.5 bg-white/20 hover:bg-white/30 text-white font-black text-xs rounded-xl transition backdrop-blur-md border border-white/20"
                >
                  상영시간표 및 예매하기
                </Link>
                <button 
                  onClick={() => { setSelectedEmotion(null); setRecommendedMovie(null); }} 
                  className="px-5 py-3.5 bg-black/20 hover:bg-black/40 text-zinc-300 font-black text-xs rounded-xl transition backdrop-blur-md border border-white/10"
                >
                  다시 고르기
                </button>
              </div>
            </div>

          </div>
        )}
      </div>
    </div>
  );
}

export default EmotionRecommendPage;
